// Source business body from Base UI v1.8.0 useButton.ts at
// 47b40521eab921c2756bf9bdb0b0f07fbfdb8c8c. MIT: THIRD_PARTY_NOTICES.md.
import { DEV } from 'esm-env';

import { error } from '@sveltery/utils/error';

import { makeEventPreventable, mergeProps } from '../../merge-props/index.js';
import { useCompositeRootContext } from '../composite/root/CompositeRootContext.js';
import type { BaseUIEvent, HTMLProps } from '../types.js';
import { useFocusableWhenDisabled } from '../../utils/useFocusableWhenDisabled.js';
import { dispatchClickWithModifiers } from '../../utils/dispatchClickWithModifiers.js';
export interface UseButtonParameters {
  disabled?: boolean;
  focusableWhenDisabled?: boolean;
  tabIndex?: number;
  native?: boolean;
  composite?: boolean;
}
export function useButton(getParameters: () => UseButtonParameters = () => ({})) {
  const elementRef = $state<{ current: HTMLElement | null }>({ current: null });
  const compositeRootContext = useCompositeRootContext(true);
  function parameters() {
    const {
      disabled = false,
      focusableWhenDisabled,
      tabIndex = 0,
      native: isNativeButton = true,
      composite: compositeProp,
    } = getParameters();
    const isCompositeItem = compositeProp ?? compositeRootContext !== undefined;
    const { props: focusableWhenDisabledProps } = useFocusableWhenDisabled({
      focusableWhenDisabled,
      disabled,
      composite: isCompositeItem,
      tabIndex,
      isNativeButton,
    });
    return { disabled, isNativeButton, isCompositeItem, focusableWhenDisabledProps };
  }
  if (DEV)
    $effect(() => {
      const isNativeButton = getParameters().native ?? true;
      const element = elementRef.current;
      if (!element) return;
      if (isNativeButton && !isButtonElement(element))
        error(
          'A component that acts as a button expected a native <button> because the `nativeButton` prop is true. Rendering a non-<button> removes native button semantics, which can impact forms and accessibility. Use a real <button> in the `render` prop, or set `nativeButton` to `false`.',
        );
      else if (!isNativeButton && isButtonElement(element))
        error(
          'A component that acts as a button expected a non-<button> because the `nativeButton` prop is false. Rendering a <button> keeps native behavior while Base UI applies non-native attributes and handlers, which can add unintended extra attributes (such as `role` or `aria-disabled`). Use a non-<button> in the `render` prop, or set `nativeButton` to `true`.',
        );
    });
  const updateDisabled = () => {
    const element = elementRef.current;
    if (!isButtonElement(element)) return;
    const { isCompositeItem, disabled, focusableWhenDisabledProps } = parameters();
    if (
      isCompositeItem &&
      disabled &&
      focusableWhenDisabledProps.disabled === undefined &&
      element.disabled
    )
      element.disabled = false;
  };
  $effect(updateDisabled);
  function getButtonProps(externalProps: HTMLProps = {}): HTMLProps {
    const { disabled, isNativeButton, isCompositeItem, focusableWhenDisabledProps } = parameters();
    const {
      onclick: externalOnClick,
      onmousedown: externalOnMouseDown,
      onkeyup: externalOnKeyUp,
      onkeydown: externalOnKeyDown,
      onpointerdown: externalOnPointerDown,
      ...otherExternalProps
    } = externalProps;
    return mergeProps(
      {
        onclick(event: MouseEvent) {
          if (disabled) {
            event.preventDefault();
            return;
          }
          (externalOnClick as ((event: MouseEvent) => void) | undefined)?.(event);
        },
        onmousedown(event: MouseEvent) {
          if (!disabled)
            (externalOnMouseDown as ((event: MouseEvent) => void) | undefined)?.(event);
        },
        onkeydown(event: BaseUIEvent<KeyboardEvent>) {
          if (disabled) return;
          makeEventPreventable(event);
          (externalOnKeyDown as ((event: BaseUIEvent<KeyboardEvent>) => void) | undefined)?.(event);
          if (event.baseUIHandlerPrevented) return;
          const isCurrentTarget = event.target === event.currentTarget;
          const currentTarget = event.currentTarget as HTMLElement;
          const isButton = isButtonElement(currentTarget);
          const isLink = !isNativeButton && isValidLinkElement(currentTarget);
          const shouldClick = isCurrentTarget && (isNativeButton ? isButton : !isLink);
          const isEnterKey = event.key === 'Enter';
          const isSpaceKey = event.key === ' ';
          const role = currentTarget.getAttribute('role');
          const isTextNavigationRole =
            role?.startsWith('menuitem') || role === 'option' || role === 'gridcell';
          if (isCurrentTarget && isCompositeItem && isSpaceKey) {
            if (event.defaultPrevented && isTextNavigationRole) return;
            event.preventDefault();
            if (!isNativeButton || isButton) {
              event.preventBaseUIHandler();
              dispatchClickWithModifiers(currentTarget, event);
            }
            return;
          }
          if (!shouldClick || isNativeButton || (!isSpaceKey && !isEnterKey)) {
            if (isCurrentTarget && isLink && isSpaceKey) event.preventDefault();
            return;
          }
          if (event.defaultPrevented) return;
          event.preventDefault();
          if (isEnterKey) {
            event.preventBaseUIHandler();
            dispatchClickWithModifiers(currentTarget, event);
          }
        },
        onkeyup(event: BaseUIEvent<KeyboardEvent>) {
          if (disabled) return;
          makeEventPreventable(event);
          (externalOnKeyUp as ((event: BaseUIEvent<KeyboardEvent>) => void) | undefined)?.(event);
          if (
            event.target === event.currentTarget &&
            isNativeButton &&
            isCompositeItem &&
            isButtonElement(event.currentTarget as HTMLElement) &&
            event.key === ' '
          ) {
            event.preventDefault();
            return;
          }
          if (event.baseUIHandlerPrevented) return;
          if (
            event.target === event.currentTarget &&
            !isNativeButton &&
            !isCompositeItem &&
            !event.defaultPrevented &&
            event.key === ' '
          ) {
            event.preventBaseUIHandler();
            dispatchClickWithModifiers(event.currentTarget as HTMLElement, event);
          }
        },
        onpointerdown(event: PointerEvent) {
          if (disabled) {
            event.preventDefault();
            return;
          }
          (externalOnPointerDown as ((event: PointerEvent) => void) | undefined)?.(event);
        },
      },
      isNativeButton ? { type: 'button' } : { role: 'button' },
      focusableWhenDisabledProps,
      otherExternalProps,
    );
  }
  const buttonRef = (element: HTMLElement | null) => {
    elementRef.current = element;
    updateDisabled();
  };
  return {
    getButtonProps,
    buttonRef,
    get element() {
      return elementRef.current;
    },
  };
}
function isButtonElement(element: Element | null): element is HTMLButtonElement {
  return element?.tagName === 'BUTTON';
}
function isValidLinkElement(element: Element | null): element is HTMLAnchorElement {
  return element?.tagName === 'A' && Boolean((element as HTMLAnchorElement).href);
}

// Native Svelte host overlap/default outro lifetime; supplemental, zero ordinary credit.
import { expect, it, vi } from 'vitest';
import { page } from 'vitest/browser';
import { render } from 'vitest-browser-svelte';
import Fixture from './TabsAttachmentLifetimeFixture.svelte';

async function replaceHostThroughNativeOutro() {
  render(Fixture);
  await page.getByRole('button', { name: 'Replace host' }).click();
  await expect.element(page.getByLabelText('Bound host')).toHaveTextContent('new');
  await expect.element(page.getByLabelText('Outro ended')).toHaveTextContent('false');
  expect(document.querySelectorAll('[data-host]')).toHaveLength(2);
  await expect.element(page.getByLabelText('Outro ended')).toHaveTextContent('true');
  expect(document.querySelectorAll('[data-host]')).toHaveLength(1);
}

it('retained old native outro cleanup leaves the current Tabs button disabled synchronization owned', async () => {
  await replaceHostThroughNativeOutro();
  await page.getByRole('button', { name: 'Disable current host' }).click();
  const currentTab = page.getByRole('tab', { name: 'Current tab' });
  await expect.element(currentTab).toHaveAttribute('aria-disabled', 'true');
  await expect.element(currentTab).not.toBeDisabled();
  await expect.element(page.getByLabelText('Bound host')).toHaveTextContent('new');
});

it('retained old native outro cleanup leaves the current Tabs button diagnostic owned', async () => {
  const messages: string[] = [];
  const spy = vi
    .spyOn(console, 'error')
    .mockImplementation((...args) => messages.push(args.join(' ')));
  try {
    await replaceHostThroughNativeOutro();
    await page.getByRole('button', { name: 'Change native expectation' }).click();
    await expect
      .poll(() => messages.some((message) => message.includes('expected a non-<button>')))
      .toBe(true);
  } finally {
    spy.mockRestore();
  }
});

// Pinned Source owner business plus native Svelte outro lifecycle supplement.
// The JSDOM WAAPI timing shim grants zero secured-browser/unchanged ordinary credit.
import { createRequire } from 'node:module';
import { resolve } from 'node:path';
import { expect, it, vi } from 'vitest';
import { flushSync, mount, tick, unmount } from 'svelte';
import Fixture from '../browser/TabsAttachmentLifetimeFixture.svelte';
const referenceRequire = createRequire(resolve('../../apps/fixtures/package.json'));
const { createElement: h, act } = referenceRequire('react');
const { createRoot } = referenceRequire('react-dom/client');
const { Tabs } = referenceRequire('@base-ui/react/tabs');

it('exact-pin Source keeps replacement button disabled synchronization and diagnostics owned', async () => {
  (
    globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT: boolean }
  ).IS_REACT_ACT_ENVIRONMENT = true;
  const host = document.createElement('div');
  document.body.append(host);
  const root = createRoot(host);
  const messages: string[] = [];
  const spy = vi
    .spyOn(console, 'error')
    .mockImplementation((...args) => messages.push(args.join(' ')));
  function source(replacement: boolean, disabled = false, nativeButton = true) {
    return h(
      Tabs.Root,
      { defaultValue: 0 },
      h(
        Tabs.List,
        {},
        h(
          Tabs.Tab,
          {
            value: 0,
            disabled,
            nativeButton,
            render: h('button', {
              key: replacement ? 'new' : 'old',
              'data-host': replacement ? 'new' : 'old',
            }),
          },
          'Current tab',
        ),
      ),
    );
  }
  try {
    await act(async () => root.render(source(false)));
    const old = host.querySelector('[data-host=old]')!;
    await act(async () => root.render(source(true)));
    const current = host.querySelector<HTMLButtonElement>('[data-host=new]')!;
    expect(current).not.toBe(old);
    expect(old.isConnected).toBe(false); // Measured React replacement has no native Svelte outro retention.
    current.disabled = true;
    await act(async () => root.render(source(true, true)));
    expect(current.getAttribute('aria-disabled')).toBe('true');
    expect(current.disabled).toBe(false);
    await act(async () => root.render(source(true, true, false)));
    expect(messages.some((message) => message.includes('expected a non-<button>'))).toBe(true);
  } finally {
    await act(async () => root.unmount());
    spy.mockRestore();
    host.remove();
  }
});

for (const behavior of ['disabled synchronization', 'diagnostic'] as const) {
  it(`native retained-host cleanup keeps current button ${behavior} owned (JSDOM timing supplement)`, async () => {
    const originalAnimate = Object.getOwnPropertyDescriptor(Element.prototype, 'animate');
    Object.defineProperty(Element.prototype, 'animate', {
      configurable: true,
      value(_frames: Keyframe[], options: KeyframeAnimationOptions) {
        let canceled = false;
        const duration = Number(options.duration ?? 0);
        const animation = {
          currentTime: 0,
          onfinish: null as (() => void) | null,
          cancel() {
            canceled = true;
            clearTimeout(timer);
          },
          effect: { getComputedTiming: () => ({ progress: 0 }) },
        };
        const timer = setTimeout(() => {
          if (!canceled) {
            animation.currentTime = duration;
            animation.onfinish?.();
          }
        }, duration);
        return animation;
      },
    });
    const messages: string[] = [];
    const spy = vi
      .spyOn(console, 'error')
      .mockImplementation((...args) => messages.push(args.join(' ')));
    const target = document.createElement('div');
    document.body.append(target);
    const component = mount(Fixture, { target });
    const click = async (text: string) => {
      [...target.querySelectorAll('button')].find((node) => node.textContent === text)!.click();
      flushSync();
      await tick();
    };
    try {
      flushSync();
      await tick();
      const old = target.querySelector('[data-host=old]')!;
      await click('Replace host');
      const current = target.querySelector<HTMLButtonElement>('[data-host=new]')!;
      expect(old.isConnected).toBe(true);
      expect(current.isConnected).toBe(true);
      await vi.waitFor(() => expect(old.isConnected).toBe(false), { timeout: 1500 });
      expect(target.querySelector('[aria-label="Bound host"]')!.textContent).toBe('new');
      if (behavior === 'disabled synchronization') {
        await click('Disable current host');
        expect(current.getAttribute('aria-disabled')).toBe('true');
        expect(current.disabled).toBe(false);
      } else {
        await click('Change native expectation');
        expect(messages.some((message) => message.includes('expected a non-<button>'))).toBe(true);
      }
    } finally {
      await unmount(component);
      spy.mockRestore();
      target.remove();
      if (originalAnimate) Object.defineProperty(Element.prototype, 'animate', originalAnimate);
      else Reflect.deleteProperty(Element.prototype, 'animate');
    }
  });
}

'use client';
import * as React from 'react';
import { isHTMLElement } from '@floating-ui/utils/dom';
import { useStableCallback } from '@base-ui/utils/useStableCallback';
import { error } from '@base-ui/utils/error';
import { SafeReact } from '@base-ui/utils/safeReact';
import { useIsoLayoutEffect } from '@base-ui/utils/useIsoLayoutEffect';
import { makeEventPreventable, mergeProps } from '../../merge-props';
import { useCompositeRootContext } from '../composite/root/CompositeRootContext';
import { BaseUIEvent, HTMLProps } from '../types';
import { useFocusableWhenDisabled } from '../../utils/useFocusableWhenDisabled';
import { dispatchClickWithModifiers } from '../../utils/dispatchClickWithModifiers';

export function useButton(parameters: UseButtonParameters = {}): UseButtonReturnValue {
  const {
    disabled = false,
    focusableWhenDisabled,
    tabIndex = 0,
    native: isNativeButton = true,
    composite: compositeProp,
  } = parameters;

  const elementRef = React.useRef<HTMLElement | null>(null);

  const compositeRootContext = useCompositeRootContext(true);
  const isCompositeItem = compositeProp ?? compositeRootContext !== undefined;

  const { props: focusableWhenDisabledProps } = useFocusableWhenDisabled({
    focusableWhenDisabled,
    disabled,
    composite: isCompositeItem,
    tabIndex,
    isNativeButton,
  });

  if (process.env.NODE_ENV !== 'production') {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    React.useEffect(() => {
      if (!elementRef.current) {
        return;
      }

      const isButtonTag = isButtonElement(elementRef.current);

      if (isNativeButton) {
        if (!isButtonTag) {
          const ownerStackMessage = SafeReact.captureOwnerStack?.() || '';
          const message =
            'A component that acts as a button expected a native <button> because the ' +
            '`nativeButton` prop is true. Rendering a non-<button> removes native button ' +
            'semantics, which can impact forms and accessibility. Use a real <button> in the ' +
            '`render` prop, or set `nativeButton` to `false`.';
          error(`${message}${ownerStackMessage}`);
        }
      } else if (isButtonTag) {
        const ownerStackMessage = SafeReact.captureOwnerStack?.() || '';
        const message =
          'A component that acts as a button expected a non-<button> because the `nativeButton` ' +
          'prop is false. Rendering a <button> keeps native behavior while Base UI applies ' +
          'non-native attributes and handlers, which can add unintended extra attributes (such ' +
          'as `role` or `aria-disabled`). Use a non-<button> in the `render` prop, or set ' +
          '`nativeButton` to `true`.';
        error(`${message}${ownerStackMessage}`);
      }
    }, [isNativeButton]);
  }

  // handles a disabled composite button rendering another button, e.g.
  // <Toolbar.Button disabled render={<Menu.Trigger />} />
  // the `disabled` prop needs to pass through 2 `useButton`s then finally
  // delete the `disabled` attribute from DOM
  const updateDisabled = React.useCallback(() => {
    const element = elementRef.current;

    if (!isButtonElement(element)) {
      return;
    }

    if (
      isCompositeItem &&
      disabled &&
      focusableWhenDisabledProps.disabled === undefined &&
      element.disabled
    ) {
      element.disabled = false;
    }
  }, [disabled, focusableWhenDisabledProps.disabled, isCompositeItem]);

  useIsoLayoutEffect(updateDisabled, [updateDisabled]);

  const getButtonProps = React.useCallback(
    (externalProps: GenericButtonProps = {}) => {
      const {
        onClick: externalOnClick,
        onMouseDown: externalOnMouseDown,
        onKeyUp: externalOnKeyUp,
        onKeyDown: externalOnKeyDown,
        onPointerDown: externalOnPointerDown,
        ...otherExternalProps
      } = externalProps;

      return mergeProps<'button'>(
        {
          onClick(event: React.MouseEvent) {
            if (disabled) {
              event.preventDefault();
              return;
            }
            externalOnClick?.(event);
          },
          onMouseDown(event: React.MouseEvent) {
            if (!disabled) {
              externalOnMouseDown?.(event);
            }
          },
          onKeyDown(event: BaseUIEvent<React.KeyboardEvent>) {
            if (disabled) {
              return;
            }

            makeEventPreventable(event);
            externalOnKeyDown?.(event);
            if (event.baseUIHandlerPrevented) {
              return;
            }

            const isCurrentTarget = event.target === event.currentTarget;
            const currentTarget = event.currentTarget as Element;
            const isButton = isButtonElement(currentTarget);
            const isLink = !isNativeButton && isValidLinkElement(currentTarget);
            const shouldClick = isCurrentTarget && (isNativeButton ? isButton : !isLink);
            const isEnterKey = event.key === 'Enter';
            const isSpaceKey = event.key === ' ';
            const role = currentTarget.getAttribute('role');
            const isTextNavigationRole =
              role?.startsWith('menuitem') || role === 'option' || role === 'gridcell';

            if (isCurrentTarget && isCompositeItem && isSpaceKey) {
              if (event.defaultPrevented && isTextNavigationRole) {
                return;
              }

              event.preventDefault();

              // Only a native-mode item that isn't a real <button> is excluded.
              if (!isNativeButton || isButton) {
                event.preventBaseUIHandler();
                dispatchClickWithModifiers(currentTarget, event);
              }

              return;
            }

            // Keyboard accessibility for native and non-native elements.
            if (!shouldClick || isNativeButton || (!isSpaceKey && !isEnterKey)) {
              // Space activates links on keyup (`role="button"` semantics, matching the
              // composite path); prevent the page scroll Space would otherwise trigger.
              // Enter is left to the browser's native link activation.
              if (isCurrentTarget && isLink && isSpaceKey) {
                event.preventDefault();
              }
              return;
            }

            // Match native buttons: preventing the keydown's default cancels activation.
            if (event.defaultPrevented) {
              return;
            }

            event.preventDefault();

            if (isEnterKey) {
              event.preventBaseUIHandler();
              dispatchClickWithModifiers(currentTarget, event);
            }
          },
          onKeyUp(event: BaseUIEvent<React.KeyboardEvent>) {
            if (disabled) {
              return;
            }

            // calling preventDefault in keyUp on a <button> will not dispatch a click event if Space is pressed
            // https://codesandbox.io/p/sandbox/button-keyup-preventdefault-dn7f0
            makeEventPreventable(event);
            externalOnKeyUp?.(event);

            if (
              event.target === event.currentTarget &&
              isNativeButton &&
              isCompositeItem &&
              isButtonElement(event.currentTarget as HTMLElement) &&
              event.key === ' '
            ) {
              event.preventDefault();
              return;
            }

            if (event.baseUIHandlerPrevented) {
              return;
            }

            // Keyboard accessibility for non interactive elements.
            // Match native buttons: preventing the keyup's default cancels Space activation.
            // Limitation: unlike a native <button>, a prevented *keydown* cannot cancel the
            // activation — no state is kept between keydown and keyup, so we can't tell
            // whether the keydown was prevented or even happened on this element.
            if (
              event.target === event.currentTarget &&
              !isNativeButton &&
              !isCompositeItem &&
              !event.defaultPrevented &&
              event.key === ' '
            ) {
              event.preventBaseUIHandler();
              dispatchClickWithModifiers(event.currentTarget as Element, event);
            }
          },
          onPointerDown(event: React.PointerEvent) {
            if (disabled) {
              event.preventDefault();
              return;
            }
            externalOnPointerDown?.(event);
          },
        },
        isNativeButton ? { type: 'button' } : { role: 'button' },
        focusableWhenDisabledProps,
        otherExternalProps,
      );
    },
    [disabled, focusableWhenDisabledProps, isCompositeItem, isNativeButton],
  );

  const buttonRef = useStableCallback((element: HTMLElement | null) => {
    elementRef.current = element;
    updateDisabled();
  });

  return {
    getButtonProps,
    buttonRef,
  };
}

function isButtonElement(elem: Element | null): elem is HTMLButtonElement {
  return isHTMLElement(elem) && elem.tagName === 'BUTTON';
}

function isValidLinkElement(elem: Element | null): elem is HTMLAnchorElement {
  return isHTMLElement(elem) && elem.tagName === 'A' && Boolean((elem as HTMLAnchorElement).href);
}

interface GenericButtonProps extends Omit<HTMLProps, 'onClick'>, AdditionalButtonProps {
  onClick?: ((event: React.SyntheticEvent) => void) | undefined;
}

interface AdditionalButtonProps extends Partial<{
  'aria-disabled': React.AriaAttributes['aria-disabled'];
  disabled: boolean;
  role: React.AriaRole;
  tabIndex?: number | undefined;
}> {}

export interface UseButtonParameters {
  /**
   * Whether the component should ignore user interaction.
   * @default false
   */
  disabled?: boolean | undefined;
  /**
   * Whether the button may receive focus even if it is disabled.
   * @default false
   */
  focusableWhenDisabled?: boolean | undefined;
  tabIndex?: NonNullable<React.HTMLAttributes<any>['tabIndex']> | undefined;
  /**
   * Whether the component is being rendered as a native button.
   * @default true
   */
  native?: boolean | undefined;
  /**
   * Whether the button is part of a composite widget.
   * When `true`, keyboard activation for Space occurs on keydown rather than keyup.
   * @default inferred from CompositeRoot context
   */
  composite?: boolean | undefined;
}

export interface UseButtonReturnValue {
  /**
   * Resolver for the button props.
   * @param externalProps additional props for the button
   * @returns props that should be spread on the button
   */
  getButtonProps: (
    externalProps?: React.ComponentPropsWithRef<any>,
  ) => React.ComponentPropsWithRef<any>;
  /**
   * A ref to the button DOM element. This ref should be passed to the rendered element.
   * It is not a part of the props returned by `getButtonProps`.
   */
  buttonRef: React.Ref<HTMLElement>;
}

export interface UseButtonState {}

'use client';
import * as React from 'react';
import { ownerDocument } from '@base-ui/utils/owner';
import { useIsoLayoutEffect } from '@base-ui/utils/useIsoLayoutEffect';
import { useStableCallback } from '@base-ui/utils/useStableCallback';
import { useBaseUiId } from '../../internals/useBaseUiId';
import { useRenderElement } from '../../internals/useRenderElement';
import type { BaseUIComponentProps, NativeButtonProps } from '../../internals/types';
import { useButton } from '../../internals/use-button';
import { ACTIVE_COMPOSITE_ITEM } from '../../internals/composite/constants';
import { useCompositeItem } from '../../internals/composite/item/useCompositeItem';
import { useCompositeRootContext } from '../../internals/composite/root/CompositeRootContext';
import type { TabsRoot } from '../root/TabsRoot';
import { useTabsRootContext } from '../root/TabsRootContext';
import { tabsStateAttributesMapping } from '../root/stateAttributesMapping';
import { useTabsListContext } from '../list/TabsListContext';
import { createChangeEventDetails } from '../../internals/createBaseUIEventDetails';
import { REASONS } from '../../internals/reasons';
import { activeElement, contains } from '../../floating-ui-react/utils';

/**
 * An individual interactive tab button that toggles the corresponding panel.
 * Renders a `<button>` element.
 *
 * Documentation: [Base UI Tabs](https://base-ui.com/react/components/tabs)
 */
export const TabsTab = React.forwardRef(function TabsTab(
  componentProps: TabsTab.Props,
  forwardedRef: React.ForwardedRef<HTMLElement>,
) {
  const {
    className,
    disabled = false,
    render,
    value,
    id: idProp,
    nativeButton = true,
    style,
    ...elementProps
  } = componentProps;

  const {
    value: activeTabValue,
    getTabPanelIdByValue,
    onValueChange,
    orientation,
    tabActivationDirection,
  } = useTabsRootContext();

  const { activateOnFocus, registerTabResizeObserverElement, tabsListElement } =
    useTabsListContext();

  const { highlightedIndex, onHighlightedIndexChange } = useCompositeRootContext();

  const id = useBaseUiId(idProp);

  const tabMetadata = React.useMemo(() => ({ disabled, id, value }), [disabled, id, value]);

  const {
    compositeProps,
    compositeRef,
    index,
    // hook is used instead of the CompositeItem component
    // because the index is needed for Tab internals
  } = useCompositeItem<TabsTab.Metadata>({
    metadata: tabMetadata,
  });

  const active = value === activeTabValue;

  const isNavigatingRef = React.useRef(false);
  const unobserveTabElementRef = React.useRef<(() => void) | null>(null);

  // Registered from the ref callback rather than an effect so the observer
  // follows the rendered element when the `render` prop swaps the host element.
  const observeTabElement = useStableCallback((element: HTMLElement | null) => {
    unobserveTabElementRef.current?.();
    unobserveTabElementRef.current = element ? registerTabResizeObserverElement(element) : null;
  });

  // Keep the highlighted item in sync with the currently active tab
  // when the value prop changes externally (controlled mode)
  useIsoLayoutEffect(() => {
    if (isNavigatingRef.current) {
      isNavigatingRef.current = false;
      return;
    }

    if (!(active && index > -1 && highlightedIndex !== index)) {
      return;
    }

    // If focus is currently within the tabs list, don't override the roving
    // focus highlight. This keeps keyboard navigation relative to the focused
    // item after an external/asynchronous selection change.
    const listElement = tabsListElement;
    if (listElement != null) {
      const activeEl = activeElement(ownerDocument(listElement));
      if (activeEl && contains(listElement, activeEl)) {
        return;
      }
    }

    // Don't highlight disabled tabs to prevent them from interfering with keyboard navigation.
    // Keyboard focus (tabIndex) should remain on an enabled tab even when a disabled tab is selected.
    if (!disabled) {
      onHighlightedIndexChange(index);
    }
  }, [active, index, highlightedIndex, onHighlightedIndexChange, disabled, tabsListElement]);

  const { getButtonProps, buttonRef } = useButton({
    disabled,
    native: nativeButton,
    focusableWhenDisabled: true,
  });

  const tabPanelId = getTabPanelIdByValue(value);

  const isPressingRef = React.useRef(false);
  const isMainButtonRef = React.useRef(false);

  // Both callers guard on `!active`, so the current value is never re-committed.
  function activate(event: React.SyntheticEvent) {
    onValueChange(
      value,
      createChangeEventDetails(REASONS.none, event.nativeEvent, undefined, {
        activationDirection: 'none',
      }),
    );
  }

  function onClick(event: React.MouseEvent<HTMLButtonElement>) {
    if (active || disabled) {
      return;
    }

    activate(event);
  }

  function onFocus(event: React.FocusEvent<HTMLButtonElement>) {
    if (active || disabled) {
      return;
    }

    if (
      activateOnFocus &&
      (!isPressingRef.current || // keyboard or touch focus
        isMainButtonRef.current) // main mouse button focus
    ) {
      activate(event);
    }
  }

  function onPointerDown(event: React.PointerEvent<HTMLButtonElement>) {
    if (active || disabled) {
      return;
    }

    isPressingRef.current = true;
    // Secondary presses (context menu, middle click) may focus the tab, but
    // must not activate it with `activateOnFocus`.
    isMainButtonRef.current = event.button === 0;

    // Registered for every button so a secondary press doesn't leave the tab
    // stuck in the pressing state, which would suppress later focus activation.
    const doc = ownerDocument(event.currentTarget);

    function handlePointerEnd() {
      isPressingRef.current = false;
      isMainButtonRef.current = false;
      doc.removeEventListener('pointerup', handlePointerEnd);
      doc.removeEventListener('pointercancel', handlePointerEnd);
    }

    doc.addEventListener('pointerup', handlePointerEnd);
    doc.addEventListener('pointercancel', handlePointerEnd);
  }

  const state: TabsTabState = {
    disabled,
    active,
    orientation,
    tabActivationDirection,
  };

  const element = useRenderElement('button', componentProps, {
    state,
    ref: [forwardedRef, buttonRef, compositeRef, observeTabElement],
    props: [
      compositeProps,
      {
        role: 'tab',
        'aria-controls': tabPanelId,
        'aria-selected': active,
        id,
        onClick,
        onFocus,
        onPointerDown,
        [ACTIVE_COMPOSITE_ITEM as string]: active ? '' : undefined,
        onKeyDownCapture() {
          isNavigatingRef.current = true;
        },
      },
      elementProps,
      getButtonProps,
    ],
    stateAttributesMapping: tabsStateAttributesMapping,
  });

  return element;
});

export type TabsTabValue = any | null;

export type TabsTabActivationDirection = 'left' | 'right' | 'up' | 'down' | 'none';

export interface TabsTabPosition {
  left: number;
  right: number;
  top: number;
  bottom: number;
}

export interface TabsTabSize {
  width: number;
  height: number;
}

export interface TabsTabMetadata {
  disabled: boolean;
  id: string | undefined;
  value: TabsTab.Value | undefined;
}

export interface TabsTabState {
  /**
   * Whether the component should ignore user interaction.
   */
  disabled: boolean;
  /**
   * Whether the component is active.
   */
  active: boolean;
  /**
   * The component orientation.
   */
  orientation: TabsRoot.Orientation;
  /**
   * The direction used for tab activation.
   */
  tabActivationDirection: TabsTab.ActivationDirection;
}

export interface TabsTabProps
  extends NativeButtonProps, BaseUIComponentProps<'button', TabsTabState> {
  /**
   * The value of the Tab.
   */
  value: TabsTab.Value;
  /**
   * Whether the Tab is disabled.
   *
   * If a first Tab on a `<Tabs.List>` is disabled, it won't initially be selected.
   * Instead, the next enabled Tab will be selected.
   * However, it does not work like this during server-side rendering, as it is not known
   * during pre-rendering which Tabs are disabled.
   * To work around it, ensure that `defaultValue` or `value` on `<Tabs.Root>` is set to an enabled Tab's value.
   */
  disabled?: boolean | undefined;
}

export namespace TabsTab {
  export type Value = TabsTabValue;
  export type ActivationDirection = TabsTabActivationDirection;
  export type Position = TabsTabPosition;
  export type Size = TabsTabSize;
  export type Metadata = TabsTabMetadata;
  export type State = TabsTabState;
  export type Props = TabsTabProps;
}
